146		}
147		return name + " (" + r.Source.String() + ")"
148	}
149	
150	// gatewayText is the gateway address, or says the destination is directly connected.
151	func (r pathRoute) gatewayText() string {
152		switch {
153		case !r.Known:
154			return routeUndetermined
155		case !r.Gateway.IsValid() || r.Gateway.IsUnspecified():
156			return gatewayDirect
157		}
158		return r.Gateway.String()
159	}
160	
161	// addrOrDash formats an address, or "-" when there is none.
162	func addrOrDash(a netip.Addr) string {
163		if !a.IsValid() {
164			return "-"
165		}
166		return a.String()
167	}
