64				hop:  netcheck.RouteHop{Interface: "tun0", Gateway: net.ParseIP("10.0.0.1")},
65				want: pathRoute{Known: true, Interface: "tun0", Gateway: netip.MustParseAddr("10.0.0.1")},
66			},
