func TestPathContainerDefaultRouteNetwork(t *testing.T) {
	a0 := ep("a", "172.18.0.5", "172.18.0.1", prioOf(0))
	b10 := ep("b", "172.19.0.5", "172.19.0.1", prioOf(10))
	tests := []struct {
		name   string
